/**
 * Vòng đời socket GCS, gắn vào store. Gọi MỘT lần, ở `App`.
 *
 * Effect trả về `sock.close()` — BẮT BUỘC. React 19 `StrictMode` chạy effect hai
 * lần ở dev để bắt đúng lỗi quên dọn dẹp; thiếu cleanup là có hai WebSocket và
 * tab tự giành quyền lái với chính nó (Phase 10). `createGcsSocket` còn mở kết
 * nối trễ một nhịp nên lượt mount đầu không kịp tạo kết nối nào (xem `ws.ts`).
 */
import { useEffect } from "react";
import { toast } from "sonner";

import { fetchEvents, fetchTelemetryHistory } from "@/lib/api";
import { hintFor, noteRepeat, repeatSignature, type RepeatRun } from "@/lib/eventGroups";
import { formatClock } from "@/lib/format";
import { ERROR_CODE_LABEL } from "@/lib/protocol";
import type { ServerEnvelope } from "@/lib/protocol";
import { setActiveSocket } from "@/lib/uplink";
import { createGcsSocket, wsUrlFromLocation } from "@/lib/ws";
import { handleControlAck, handleControlError, warnOverdueCommands } from "@/hooks/controlUplink";
import { handleMissionAck, handleMissionError, handleMissionProgress } from "@/hooks/missionUplink";
import { useControlStore } from "@/store/control";
import { telemetryHistory } from "@/store/history";
import { countBytes, countFrame, flushFrameCounts, useSessionStore } from "@/store/session";
import { useMissionStore } from "@/store/mission";
import { fromServerEvent, useTelemetryStore, webEvent } from "@/store/telemetry";
import type { LogEntry } from "@/store/telemetry";

/** Lấy bao nhiêu sự kiện cũ lúc mở trang (`GET /api/events?limit=`). */
export const EVENT_HISTORY_LIMIT = 100;

/**
 * Chỉ bật toast cho sự kiện `error` xảy ra trong chừng này giây gần đây. Backend
 * phát lại 50 sự kiện cũ cho mỗi socket mới — không có ngưỡng này thì mỗi lần
 * nối lại, mọi lỗi cũ lại nhảy toast.
 */
export const TOAST_MAX_AGE_S = 10;

/** Nạp sẵn lịch sử backend giữ chừng này giây — biểu đồ có dữ liệu ngay khi mở. */
export const HISTORY_SEED_SECONDS = 600;

/** Chuỗi lặp của từng lỗi đã nhận khi trang đang mở (khoá: `repeatSignature`). */
const errorRuns = new Map<string, RepeatRun>();
/** Chữ ký của các toast lỗi còn trên màn hình. */
const openErrorToasts = new Set<string>();

/**
 * Mỗi chuỗi lỗi lặp lại chỉ một toast. FC nhắc "Takeoff blocked" 2 s một lần và PreArm 30 s một
 * lần: bật toast mới cho từng lần là toast đỏ nối nhau không dứt. Lần lặp chỉ cập nhật ×N trên
 * toast còn đang hiện (cùng `id`); toast đã tắt thì thôi, dòng ×N ở trang Nhật ký vẫn đủ.
 */
function toastError(entry: LogEntry): void {
  const sig = repeatSignature(entry);
  const run = noteRepeat(errorRuns, sig, entry.ts);
  if (run.count > 1 && !openErrorToasts.has(sig)) return;
  openErrorToasts.add(sig);
  const closed = () => openErrorToasts.delete(sig);
  const head = hintFor(entry.message) ?? entry.code;
  toast.error(entry.message, {
    id: sig,
    description: run.count > 1 ? `${head} · ×${run.count} từ ${formatClock(run.firstTs)}` : head,
    onAutoClose: closed,
    onDismiss: closed,
  });
}

function handleMessage(msg: ServerEnvelope): void {
  const store = useTelemetryStore.getState();
  countFrame(msg.type);
  switch (msg.type) {
    case "telemetry":
      store.applyTelemetry(msg.data);
      telemetryHistory.push(msg.data);
      useSessionStore.getState().onArmed(msg.data.armed, msg.data.relative_alt);
      return;
    case "status":
      store.applyStatus(msg.data);
      useControlStore.getState().syncWebControl(msg.data.safety.web_control_enabled);
      return;
    case "detection":
      store.applyDetection(msg.data);
      return;
    case "event": {
      if (msg.data.code === "mission.progress") handleMissionProgress(msg.data.detail);
      const entry = fromServerEvent(msg.data, msg.ts);
      const isNew = store.pushEvent(entry);
      // Toast chỉ cho `error`. Toast cho mọi `info` dạy người dùng phớt lờ
      // toast — đúng lúc cái quan trọng hiện ra thì họ không nhìn nữa.
      if (isNew && entry.level === "error" && Date.now() / 1000 - entry.ts <= TOAST_MAX_AGE_S) {
        toastError(entry);
      }
      return;
    }
    case "error": {
      // Lỗi của lần nạp mission: panel mission tự hiện và tự bật toast phù hợp.
      if (handleMissionError(msg.data)) return;
      // Lỗi của lệnh bay (Phase 10): gắn về đúng nút, gộp lỗi lái tay lặp lại.
      if (handleControlError(msg.data)) return;
      // Backend từ chối một message của chính tab này.
      const label = ERROR_CODE_LABEL[msg.data.code as keyof typeof ERROR_CODE_LABEL] ?? msg.data.code;
      store.pushEvent(webEvent("warn", `ws.error.${msg.data.code}`, `${label}: ${msg.data.message}`, { ref: msg.data.ref ?? null }));
      toast.error(label, { description: msg.data.message });
      return;
    }
    case "ack":
      // Lệnh bay (Phase 10) khớp theo `ref`; không khớp thì là của nạp mission.
      if (handleControlAck(msg.data)) return;
      handleMissionAck(msg.data);
      return;
    case "pong":
      return;
  }
}

async function loadTelemetryHistory(signal: AbortSignal): Promise<void> {
  try {
    const body = await fetchTelemetryHistory(HISTORY_SEED_SECONDS, { signal });
    telemetryHistory.seed(body.samples.map((s) => ({ t: s.ts * 1000, d: s.data })));
  } catch (err) {
    if (signal.aborted) return;
    // Không có lịch sử thì biểu đồ bắt đầu từ lúc mở trang — ghi lại, không chặn.
    useTelemetryStore
      .getState()
      .pushEvent(webEvent("info", "api.history_failed", `Chưa nạp được lịch sử telemetry: ${(err as Error).message}`));
  }
}

async function loadEventHistory(signal: AbortSignal): Promise<void> {
  try {
    const history = await fetchEvents(EVENT_HISTORY_LIMIT, { signal });
    const now = Date.now() / 1000;
    for (const e of history) useTelemetryStore.getState().pushEvent(fromServerEvent(e, now));
  } catch (err) {
    if (signal.aborted) return;
    // Không có lịch sử thì bảng vẫn chạy với sự kiện trực tiếp — chỉ ghi lại, không chặn.
    useTelemetryStore
      .getState()
      .pushEvent(webEvent("warn", "api.events_failed", `Không lấy được lịch sử sự kiện: ${(err as Error).message}`));
  }
}

export function useWebSocket(): void {
  useEffect(() => {
    const store = useTelemetryStore.getState();
    const history = new AbortController();
    void loadEventHistory(history.signal);
    void loadTelemetryHistory(history.signal);

    let wasOpen = false;
    const sock = createGcsSocket({
      url: wsUrlFromLocation(window.location),
      onMessage: handleMessage,
      onFrame: (at, size) => {
        store.markMessage(at);
        countBytes(size);
      },
      onNotice: (n) => store.pushEvent(webEvent(n.level, n.code, n.message, n.detail ?? null)),
      onState: (state, info) => {
        store.setConnection(state, info.nextRetryAt);
        if (state === "open") {
          wasOpen = true;
          useSessionStore.getState().onSocketOpen(info.reconnected);
          if (info.reconnected) store.pushEvent(webEvent("info", "ws.reconnected", "Đã nối lại với backend"));
        } else if (state === "closed" && wasOpen) {
          wasOpen = false;
          useMissionStore.getState().onSocketLost();
          useControlStore.getState().onSocketLost();
          useSessionStore.getState().onSocketClosed();
          store.pushEvent(webEvent("warn", "ws.lost", "Mất kết nối với backend — đang thử nối lại"));
        }
      },
    });
    setActiveSocket(sock);
    const overdueTimer = setInterval(warnOverdueCommands, 1000);
    const rateTimer = setInterval(flushFrameCounts, 1000);

    return () => {
      clearInterval(overdueTimer);
      clearInterval(rateTimer);
      history.abort();
      setActiveSocket(null);
      sock.close();
    };
  }, []);
}
